# Pilot translations, written by Claude in-conversation (no API).
# Conventions used, which become the translation prompt for the real run:
# - only core + common Linku words; no quotation marks (dialogue as "toki e ni: ...")
# - names adapted to toki pona sounds and always after a head word (soweli Sapo, mije Ten)
# - "Once upon a time" -> "tenpo pini la"; "One day" -> "tenpo suno wan la"
# - "lived happily ever after" -> "tenpo ale la ... li pilin pona"
# - en only joins subjects; repeated objects use e ... e

NAMES = {
    "Spot": "Sapo", "Bob": "Pope", "Tim": "Ten", "Blue": "Pulu", "Bunny": "Pani", "Tom": "Ton",
    "Lily": "Lili", "Jane": "Sen", "Sam": "San", "Betty": "Peti", "Tina": "Kina", "Amy": "Ami",
    "Sue": "Su", "Kitty": "Kisi", "Rocky": "Loki", "Pip": "Pipu", "Billy": "Pili", "Anna": "Ana",
    "Lucy": "Lusi", "Oxygen": "Okusen",
}

TP = {
"ts-valid-0050": "tenpo pini la soweli Sapo li lon. soweli Sapo li awen wawa. ona li olin e musi. tenpo suno wan la soweli Sapo li kute e toki pi jan pona ona. jan pona wan li toki e ni: mi mute li wile musi suli! soweli Sapo li pilin wawa. ona kin li wile musi suli. ona li tawa jan pona ona li toki e ni: mi ken ala ken musi suli kin? jan pona ona li pilin pona li toki e ni: ken a, soweli Sapo o! mi mute ale o musi suli! ona mute li musi li moku e moku pona li kalama tan pilin pona. soweli Sapo li pilin pona mute. jan pona ona kin li pilin pona. tenpo ale la ona mute li pilin pona.",
"ts-valid-0080": "tenpo pini la pipi lili Pope li lon. jan mute li olin e pipi Pope. jan pona ale ona li olin mute e ona. pipi Pope li lon kasi suli laso. tenpo suno wan la pipi Pope li musi lon poka pi jan pona ona. pipi sin li kama. pipi sin li pilin lili. ona li toki e ni: toki! nimi mi li Ten. mi ken ala ken musi kin? pipi Pope en jan pona ona li pilin pona tan jan pona sin. ona mute ale li musi lon tenpo sama li pilin pona mute. pipi Ten li pilin pona tan ni: ona li lon kulupu pi pipi Pope. tenpo ni la jan mute li olin e pipi Ten kin. ona mute ale li awen pilin pona lon kasi suli laso.",
"ts-valid-0084": "tenpo pini la waso Pulu li lon. ona li sona pona e kalama musi. ona li ken kalama e kalama musi pona lon ma kasi. soweli ale li olin e ni: ona li kute e kalama musi pi waso Pulu. tenpo suno wan la waso Pulu li lukin e kiwen pimeja suno. kiwen ni li kiwen seli. waso Pulu li pana e kiwen seli tawa jan pona ona, soweli Pani. soweli Pani li olin e kiwen seli li kepeken e ona li sitelen e sitelen lon ma. waso Pulu en soweli Pani li musi e kiwen seli li kalama musi lon tenpo suno ale. soweli ale pi ma kasi li kama li lukin e sitelen li kute e kalama musi pi waso Pulu. ona mute ale li pilin pona lon tenpo sama.",
"ts-valid-0139": "tenpo pini la ma tomo lili li lon. ona li ma pi utala ala. ma leko suli li lon insa ona. jan lili mute li musi lon ma leko. ona mute li pilin pona mute. tenpo suno wan la meli lili li lukin e musi pi kipisi mute lon ma. musi ni li jo e kipisi leko mute. meli lili li wile pini e musi ni. ni la ona li toki tawa jan pona ona li wile e pana pona tan ona mute. ona mute ale li pali lon tenpo sama. ona mute li pana e kipisi leko lon ma pona ona. tenpo lili la musi li pini. jan lili li pilin pona li pilin suli. tenpo suno ni li musi tawa ona mute lon ma tomo pona.",
"ts-valid-0162": "tenpo suno wan la soweli lili en soweli suli li lon ma kasi. soweli lili li lape pona lon supa. soweli suli li lon poka pi ilo seli. soweli suli li toki e ni: mi wile musi! soweli lili li lukin e soweli suli li toki e ni: pona, mi mute o musi! ona tu li musi lon poka pi ilo seli. soweli suli li tawa wawa. soweli lili li tawa sewi. ona tu li pilin pona. tenpo ni la ilo seli li pakala e linja monsi pi soweli suli. soweli suli li toki e ni: a, ike! soweli lili li tawa wawa li wile pona e ona. soweli lili li luka lili e monsi pi soweli suli. soweli suli li pilin pona. ona tu li musi sin li jo e tenpo suno pona.",
"ts-valid-0170": "tenpo suno wan la mije lili Ten li tawa lon nasin. mama ona li tawa lon poka ona. ona tu li lukin e ijo jaki mute lon poka tomo ona. mije Ten li lukin pona li lukin e ijo suno lon insa pi ijo jaki. mije Ten li toki e ni: mama o, o lukin! mi lukin e ijo suno. mi ken ala ken jo e ona? mama ona li toki e ni: ken. taso sina o awen. mije Ten li tawa e ijo jaki kepeken nasin awen li lukin e tomo tawa lili musi. ona li pilin pona mute. ona li pana e tomo tawa lili tawa mama. mama li pilin pona. tan tenpo ni la mije Ten li lukin pona e ma ale lon poka ona li lukin e ijo mani mute. ona li kama sona e ni: jan li lukin pona la ona li ken alasa e ijo pona.",
"ts-valid-0171": "tenpo pini la tomo tawa telo lili li lon. ona li wile tawa poka telo. tenpo suno wan la ona li lukin e ijo suli. ijo ni li ike li suli. tomo tawa telo li wile pana e pona. ni la ona li tawa e ijo suli tawa poka telo. ijo suli li pana e pilin ike tawa tomo tawa telo. tomo tawa telo li tawa lili li pilin lape. pini la ona li ken ala tawa e ijo suli. tomo tawa telo li pini tawa li awen lon poka telo. tenpo ale la ona li pilin ike.",
"ts-valid-0174": "tenpo pini la meli lili pona Lili li tawa lon nasin. ona li lukin e poki mani pona lon ma. meli Lili li olin e poki li wile sona e ni: jan seme li jo e poki? meli Lili li toki tawa jan pona ona: sina sona ala sona e jan ni? jan ni li weka e poki ni. jan pona ona li sona ala. taso ona mute ale li pilin pona tan poki. ona mute li pilin e ni: poki li pona lukin mute. pini la meli Lili li lukin e meli suli pi pilin ike. meli suli ni li weka e poki ona. meli Lili li pana sin e poki tawa ona la ona li pilin pona mute. meli suli li toki e ni: meli lili pona o, sina pona! meli Lili li pilin pona tan ni: ona li pana e pona.",
"ts-valid-0207": "tenpo pini la suno wawa li lon. suno li jan pona pi ilo lili. ilo ni li sona e seli. ona tu li lon sewi suli. tenpo suno wan la suno li wile musi pi alasa len. suno li len e ona sama lon monsi pi kon walo suli. ilo li alasa mute. taso ona li ken ala lukin e suno. ni la ilo li wile e pana pona tan kon tawa. kon tawa li weka e kon walo suli. suno li kama lon. ona tu li kalama musi. suno wawa en ilo li pilin pona li musi lon tenpo suno ale.",
"ts-valid-0235": "tenpo pini la waso lili li lon. ona li wawa ala. waso li jo e ilo pi linja lawa. ona li wile tawa sike lon palisa kasi. tenpo suno wan la waso li tawa sike la ona li lukin e soweli suli. soweli suli li wile musi e waso. waso li pilin monsuta. taso ona li jo e sona sin. ona li pana e ilo pi linja lawa tawa soweli. soweli li olin mute e ilo. ona li sona ala e waso li musi e ilo lon tenpo suno ale. waso li awen pona li pilin pona. soweli en waso li kama jan pona.",
"ts-valid-0303": "tenpo pini la waso suli li lon. soweli ale li wile sona e sona len ona. tenpo suno wan la waso li pana e sona ona. ona li toki e ni: mi sona e kule ale lon sewi! jan ale li pilin wawa a! ona mute li lukin tawa sewi li lukin e kule mute lon sewi. jan ale li toki e ni: waso li sona mute. tan tenpo ni la ona mute ale li wile awen e waso. ona mute li wile ala e ni: jan ante li sona e sona len ni. ni la waso suli li awen pilin pona li awen lon sewi lon poka pi kule ale ona. pini.",
"ts-valid-0320": "tenpo suno wan la mije Ton li jo e soweli tawa. soweli ni li pona ala lukin. taso mije Ton li olin e ona. ona tu li pali lon ma pan. soweli li pana e pona tawa mije Ton li tawa e ijo. tenpo suno wan la soweli li pakala. mije Ton li toki e ni: a ike a! jan pona mi o, mi wile pona e sina. mije Ton li pana e len misikeke lon noka soweli. soweli li pilin pona. ona tu li tawa sin tawa pali. ona tu li pilin pona lon tenpo sama. soweli pi pona lukin ala li wawa li pana e pona mute tawa mije Ton. mije Ton li toki e ni: jan pona mi o, sina pona. sina soweli pona nanpa wan. ona tu li awen pilin pona lon ma pan.",
"ts-valid-0343": "tenpo suno wan la mije lili Ten li lukin e pipi walo. ona li wile pana e sona pi pipi ni tawa jan pona ona, meli Sen. mije Ten li tawa e pipi tawa tomo pi meli Sen. ona li kalama e lupa tomo. mije Ten li toki e ni: meli Sen o, o lukin e ijo mi! mi wile e ni: sina sona e jan pona sin mi, pipi ni! meli Sen li lukin e pipi walo li pilin pona. ona li toki e ni: toki, pipi o! ona tu li musi e pipi lon ma kasi. tenpo lili la ona tu li toki e ni tawa pipi: tawa pona. mije Ten en meli Sen li pilin pona tan ni: ona li ken lukin e jan pona sin li musi e ona.",
"ts-valid-0368": "tenpo pini la mije lili pi pilin musi li lon. nimi ona li San. mije San li jo e lipu. lipu ni li lipu pi tenpo suno. ona li olin sitelen lon lipu ona lon tenpo suno ale. ni li musi pona nanpa wan tawa ona. tenpo suno wan la mije San li kama lukin e soweli lili pi ken toki. nimi ona li Ton. soweli Ton li toki e ni: toki, mije San o! mi mute o toki! mije San li pilin pona mute. ona tu li toki e suno e mun e mun lili. ona tu li kama jan pona. mije San li pana e lipu ona tawa soweli Ton li lukin e ona. ona tu li sitelen e sitelen li sitelen e toki musi. ona tu li kalama musi li musi lon tenpo suno ale. mije San en soweli Ton li pilin pona mute. tenpo ale la ona tu li pilin pona.",
"ts-valid-0438": "tenpo pini la waso kule Peti li lon. waso Peti li olin e tawa kon e kalama musi. ona li jo e jan pona mute lon ma kasi. tenpo suno wan la waso Peti li kama lukin e soweli lili San. soweli San li pilin ike tan ni: ona li ken ala lawa pona e mani ona. ona li wile esun e kili kiwen. taso mani ona li weka. waso Peti li wile pana e pona tawa jan pona ona. waso Peti li toki e ni: soweli San o, mi mute o alasa e mani! ona tu li alasa lon ma kasi li lukin e mani sike suno. soweli San li pilin pona li toki e pona tawa waso Peti. tenpo ni la soweli San li ken esun e kili kiwen. ona tu li jo e tenpo suno musi.",
"ts-valid-0457": "tenpo pini la meli lili li lon. ona li pilin ike tan ni: sijelo ona li pona ala. ona li toki ike tawa mama ona tan ni: insa ona li pakala. mama ona li pona mute li pana e misikeke tawa meli lili. misikeke li jaki lon uta. taso ona li pona e meli lili. meli lili li moku wawa e misikeke. tenpo lili la ona li pilin pona mute. ona li pilin pona tan ni: ona li wile ala toki ike. pini.",
"ts-valid-0468": "tenpo pini la soweli lili Ton li lon. ona li pilin suli. soweli Ton li olin e moku kala. tenpo suno wan la soweli Ton li kama lukin e soweli lili pona Kina. ona tu li musi li olin mute e ona sama. soweli Ton li toki tawa soweli Kina: mi wile kama jan olin sina. mi tu li ken moku e kala li pilin pona. soweli Kina li pilin pona li toki e ni: soweli Ton o, mi wile. ni la soweli Ton en soweli Kina li kama jan olin. ona tu li musi suli lon poka pi jan pona ale ona. ona mute li moku e kala mute li tawa musi lon tenpo pimeja ale. soweli Ton en soweli Kina li pana e pilin pona tawa jan ale.",
"ts-valid-0479": "tenpo pini la soweli lili li lon. ona li tawa wawa li olin e tawa wawa. tenpo suno wan la ona li tawa lon poka pi kasi suli. ona li tawa wawa mute li weka e kasi suli. ona li awen tawa wawa. ona li tawa lon poka tomo. ona li tawa lon poka pi sinpin lili. ona li tawa lon ma kasi mute. ona li tawa wawa mute li weka e ijo ale pi tenpo pini. pini la ona li kama lon poka telo li awen lili. ona li pilin pona. ona li lukin e monsi li pilin pona tan ijo ale ni.",
"ts-valid-0553": "tenpo pini la soweli lili loje walo li lon. ona li olin e tawa wawa. tenpo suno wan la ona li tawa musi lon ma. ona li lukin e nasin sewi. nasin ni li lon sewi pi telo lili. soweli li wile tawa wawa lon nasin sewi. ni la ona li tawa wawa lon nasin sewi. soweli li tawa lon nasin sewi la ona li kama sona e jan pona sin. jan pona ni li waso telo lili. soweli lili en waso telo lili li musi lon tenpo sama. ona tu li tawa wawa li pilin musi. ona tu li pilin pona mute.",
"ts-valid-0560": "tenpo suno wan la meli lili Ami li musi lon ma. ona li olin e tawa sewi. meli Ami li lukin e ni: mama ona li telo e len. ona li wile pana e pona tawa mama. meli Ami li open jo e len. ona li pana e len lon poki len. mama ona li pilin pona tan pona ona. ona tu li telo e len lon tenpo sama. meli Ami li pilin pona tan ni: ona li pana e pona tawa mama. sona pi toki ni li ni: o pana e pona tawa jan ante. sina pana e pona tawa jan ante la ona li pilin pona. pona li pona mute.",
"ts-valid-0599": "mama li pali e pan suwi lon poki. ona li wan e ijo mute li pana e poki lon poki seli. ona li open e ilo tenpo tan ni: ona li wile ala weka e sona. tenpo lili la ilo tenpo li kalama. mama li weka e poki tan poki seli li lukin e ni: pan suwi li pona. ona li jelo pimeja li pana e kon pona. mama li pilin pona li kipisi e pan suwi. ni la ona li pana e kipisi lon supa moku li tawa e ona tawa supa. mama li toki e ni: jan seme li wile e pan suwi? jan ale li pilin pona li toki e ni: mi! ona mute ale li moku e pan suwi. pan suwi li pona mute a!",
"ts-valid-0606": "tenpo suno wan la mije lili Ten en meli lili Su li tawa ma kasi. ona tu li lukin e soweli suli. soweli ni li moku e kasi. soweli li wile jo e ale li wile ala pana e kasi ona. mije Ten li toki e ni: soweli o, mi ken ala ken moku e kasi kin? soweli li toki ala e pana. ona li awen moku e kasi ale. meli Su li pilin ike li toki e ni: soweli o, pana li pona. soweli li pilin e ni li wile pana e kasi tawa jan lili tu. ona mute ale li moku e kasi lon tenpo sama li kama jan pona.",
"ts-valid-0614": "tenpo pini la soweli Sapo li lon. soweli Sapo li awen pona. ona li olin e jan pona ona li jo e ona lon luka. ona li jo e poki telo. poki telo ni li musi pona nanpa wan tawa ona. tenpo suno wan la soweli Sapo li tawa ma kasi musi kepeken poki telo ona. ona li lukin e jan pona ona, soweli lili Kisi. soweli Sapo li jo e soweli Kisi lon luka. ona tu li musi e poki telo. ona tu li pilin musi mute. tenpo ni la ma li kama pimeja. soweli Sapo en soweli Kisi li pilin lape mute. ona tu li weka e sona pi poki telo lon ma kasi. ona tu li tawa tomo la ona li pilin ike tan ni: poki telo li weka. ona tu li ken ala musi e ona. pini.",
"ts-valid-0637": "tenpo pini la soweli lili li lon ma kasi suli. soweli ni li wile sona mute. ona li olin lukin e ijo ale li olin luka e ijo ale. tenpo suno wan la soweli lili li lukin e kasi suli. ona li wile tawa sewi kasi. ona li alasa mute. taso ona li ken ala. ona li pilin ike tan ni: ona li ken ala kama lon sewi kasi. soweli lili li awen alasa la akesi linja suli li kama tan kasi. akesi ni li pona ala. akesi li pakala e soweli lili. soweli lili o awen pona lon ma kasi suli. pini.",
"ts-valid-0656": "tenpo pini la jan lili sewi li lon. ona li jo e ilo open. ilo open li ken open e lupa suli. lupa li lon ma kasi pona. jan lili sewi li olin musi lon ma kasi. tenpo suno wan la ona li kama lukin e soweli. soweli ni li ken ala kute. soweli li wile musi lon ma kasi kin. jan lili sewi li wile pana e pona tawa soweli. ona li kepeken e ilo open ona li open e lupa. jan lili sewi en soweli li tawa insa pi ma kasi. ona tu li musi li pilin musi. ona tu li pilin pona. jan lili sewi en soweli li kama jan pona.",
"ts-valid-0696": "tenpo pini la jan pali pona li lon. ona li wile pona e ijo pakala. tenpo suno wan la ona li lukin e ilo musi pakala lon ma kasi musi. ilo pakala li pana e pilin ike tawa jan lili. ona mute li ken ala musi kepeken ona. jan pali li toki e ni: mi pona e ilo musi! ona li jo e ilo ona li pali wawa. taso ilo musi li awen pakala. ona li alasa sin mute. jan lili li lukin li awen. pini la jan pali li pona e ilo musi! jan lili li pilin pona mute. ona mute li ken musi sin kepeken ilo musi. ona mute li toki e ni: jan pali pona o, sina pona! ona mute ale li musi lon tenpo sama lon ma kasi musi.",
"ts-valid-0713": "tenpo pini la soweli lili Sapo li lon. ona li lon tomo lili. tomo ni li jo e tomo pi tomo tawa. ona li olin musi e ijo musi ona lon tomo pi tomo tawa. tenpo suno wan la soweli Sapo li lukin e kiwen sijelo pona lon tomo pi tomo tawa. ona li pilin pona mute! ona li open moku e kiwen sijelo. kiwen sijelo ni li pona nanpa wan tawa uta ona. soweli Sapo li moku e kiwen sijelo lon tenpo suno ale. ona li wile ala pini. tenpo lape li kama la ona li tawa e kiwen sijelo lon poka ona. tenpo suno ni li pona nanpa wan tawa soweli Sapo.",
"ts-valid-0732": "tenpo pini la supa moku suli li lon. supa ni li ike tawa sijelo. supa li lon tomo lili. kulupu mama pona li lon tomo ni kin. tenpo suno wan la kulupu mama li wile awen li moku lon supa. ona mute li pana e moku lon supa. taso supa li ike mute la ona mute li ken ala moku. kulupu mama li pilin ike. ona mute li alasa pona e supa. taso ona mute li ken ala. kulupu mama li awen pilin ike li wile moku. supa ike li ante ala. tenpo ale la kulupu mama li moku ala lon supa. pini.",
"ts-valid-0778": "tenpo pini la meli lili Lili li olin lukin e ni: mama ona li pali e moku. tenpo suno wan la mama li pali e moku suwi. meli Lili li wile moku e ona. taso jan sama lili ona, mije Ton, li pilin utala. ona li wile musi e sike. ona li wile ala lukin e ni: mama li pali e moku. ni la ona li pana wawa e sike. sike li pakala e moku suwi. moku suwi li tawa anpa. mama li pilin ike. taso meli Lili li jo e sona sin. ona li pana e pona tawa mama li pali e moku suwi sin. ona mute ale li moku e ona lon tenpo sama. jan ala li pilin utala. ona mute li pilin pona li pilin suli lon insa.",
"ts-valid-0799": "tenpo suno wan la jan pona tu li lon tomo lape. jan wan li toki tawa jan ante: sina wile ala wile lukin e sitelen tawa? jan pona li toki e ni: wile a! ni la ona tu li tawa tomo suli. mama ona li pana e sitelen tawa suwi tawa ona. ona tu li awen lon supa monsi li open lukin. ona tu li kalama musi mute lon tenpo pi sitelen tawa. ona tu li pilin e ni: sitelen tawa li musi mute li suwi. sitelen tawa li pini la jan nanpa wan li toki tawa jan ante: sitelen tawa li pona ala pona tawa sina? jan pona li pilin pona li toki e ni: pona a! ni li musi mute!",
"ts-valid-0815": "tenpo pini la soweli Sapo li lon. ona li wile ala pali. ona li lon tomo lili. lupa li lon sewi tomo. telo sewi li kama la telo li kama insa tomo. tenpo suno wan la soweli Sapo li lukin e sitelen. sitelen li toki e ni: o pini e lupa sina. soweli Sapo li pilin e ni: mi wile ala e telo lon tomo mi. ni la ona li wile pini e lupa. soweli Sapo li pali wawa li pini e lupa lon tomo ona. ona li pini e pali la telo sewi li awen lon ma. soweli Sapo li pilin pona li wile pali. ona li kama sona e ni: pali pi pona ijo li ken musi.",
"ts-valid-0841": "tenpo pini la tomo esun sin li lon. len suli pona li lon tomo esun. len ni li loje li seli. meli lili Lili li lukin e len li wile e ona. meli Lili li toki tawa mama ona: mi ken ala ken jo e len loje? mama ona li toki e ni: o alasa e len lon sijelo sina. meli Lili li len e sijelo kepeken len. len li pona tawa sijelo ona. ona li pilin pona li pilin seli lon len sin ona. ona tu li esun e len tan tomo esun sin. meli Lili li len e len loje lon ma ale. ona li olin mute e len pona ona. tenpo ale la ona li pilin pona.",
"ts-valid-0852": "tenpo pini la kiwen lili Loki li lon. ona li lon poka telo suli. ko mute li lon ma ni. kiwen Loki li jo e jan pona mute. jan pona ona li waso mute li pipi telo mute. tenpo suno wan la telo suli wawa li kama lon poka telo. jan pona pi kiwen Loki, pipi telo, li toki e ni: kiwen Loki o, o awen! telo wawa li kama! kiwen Loki li kute li tawa weka tan telo. telo wawa li weka la kiwen Loki en jan pona ona li musi lon ko. ona mute li pilin pona li awen pona tan ni: ona mute li kute e toki pi pipi telo. ona mute li jo e tenpo suno musi lon poka telo.",
"ts-valid-0879": "tenpo suno wan la mije lili Ten li tawa lon nasin. ona li lukin e kiwen suli. kiwen li ike. ona li toki ike tawa mije Ten. mije Ten li pilin ike. mije Ten li jo e sona sin. ona li toki e ni tawa kiwen: mi pakala. kiwen li sona ala e ni. kiwen li pilin ike tan pali ona. ona li toki e ni tawa mije Ten: mi pakala kin. tenpo ni la mije Ten en kiwen li jan pona. ona tu li musi li pilin musi. ona tu li pilin pona. kiwen ike li kama kiwen pona.",
"ts-valid-0901": "tenpo pini la soweli tawa li lon. soweli ni li olin pali e moku. tenpo suno wan la ona li pali e pan suwi suli. ona li pilin pona mute. soweli lili monsuta li lukin e soweli tawa e pan suwi. soweli lili li wile e pan suwi kin. soweli lili monsuta li tawa sewi lon soweli tawa. soweli tawa li pilin monsuta. taso ijo nasa li kama. soweli lili monsuta li weka ala e pan suwi. ona li wile pana e pona lon pali moku taso. soweli tawa en soweli lili monsuta li kama jan pona. ona tu li pali e pan suwi sin lon tenpo sama. ona tu li pilin pona.",
"ts-valid-0904": "tenpo suno wan la waso lili Pipu li tawa wawa. waso Pipu li jo e pona mute. ona li tawa wawa mute. ona li olin e tawa wawa lon ko lete walo. suno li suno mute. sewi li laso. waso Pipu li lukin e jan pona ona, soweli telo San. soweli telo San li toki e ni: toki, waso Pipu o! mi mute o tawa wawa lon tenpo sama! waso Pipu en soweli San li tawa wawa li musi lon ko lete. ona tu li pilin musi mute. tenpo lili la ona tu li pilin lape. ona tu li awen lon ma li lukin e sewi. ona tu li pilin pona tan ni: ona tu li jan pona. waso Pipu en jan pona ona li jo e tenpo suno pona.",
"ts-valid-0949": "tenpo suno wan la soweli lili musi Ton li tawa jan pona ona, soweli suli San. soweli Ton li wile musi lon poka pi soweli San. soweli San li pilin pona tan ni: ona li lukin e soweli Ton. ona tu li olin musi lon tenpo sama. soweli Ton li wile e ni: soweli San li pana e ko walo tawa ona. soweli San li pana e ko tawa soweli Ton. soweli Ton li pana e ko lon ma. ona tu li musi e ko li pilin musi. taso ijo nasa li kama. ko li kama pan suwi suli! soweli Ton en soweli San li pilin nasa mute. ona tu li kalama musi li moku e pan suwi lon tenpo sama. ona tu li jo e tenpo suno pona.",
"ts-valid-0952": "tenpo pini la kiwen suli li lon. kiwen li lon ma. ona li ike ala. taso ona li pilin ike lili. tenpo suno wan la kiwen li kama sona e jan pona sin. nimi pi jan pona ni li Okusen. kon Okusen li ike ala kin. ona tu li olin musi lon tenpo sama. kiwen en kon Okusen li musi lon tenpo suno ale. ona tu li jan pona pi pilin pona. ona tu li lon ma li lukin e sewi. kiwen li pilin ike ala lon tenpo ni.",
"ts-valid-1072": "tenpo suno wan la soweli sona Sapo li lon tomo lili. ona li wile pana e pona tawa jan. soweli Sapo li jo e pali. pali ona li ni: ona li pana e pona lon tenpo ike. tenpo suno wan la soweli Sapo li lukin e ilo musi pakala. meli lili li pilin ike. ona li wile e pona. soweli Sapo li sona e nasin pona. ona li wile ante e ilo musi pakala kepeken ilo musi sin. soweli Sapo li tawa tomo esun. ona li lukin e ilo musi sin. ona li tawa e ilo musi sin tawa meli lili. meli lili li pilin pona sin. soweli Sapo li pilin pona. ona li pana e pona lon tenpo ike kepeken sona ona li ante e ilo musi.",
"ts-valid-1075": "tenpo pini la jan pi tenpo mute li lon. ona li lon tomo lili. tenpo suno wan la ona li lukin e palisa kiwen suli lon anpa tomo. ona li wile awen e ona. jan ni li kama lukin e jan pona. ona li pana e palisa kiwen tawa lukin pi jan pona ona. jan pona ona li toki e ni: a, palisa kiwen ni li suli mute! mi mute o awen e toki pi palisa ni! jan pi tenpo mute li pilin pona li tawa e lawa ona. ona tu li open awen e toki. jan pi tenpo mute li toki e palisa kiwen. ona tu li pilin musi mute. ona tu li pini la ona tu li kute e toki. ona tu li kalama musi li pilin pona mute.",
"ts-valid-1084": "tenpo pini la ma tomo lili li lon. soweli Pili li lon ma ni. ona li soweli pi selo ike. soweli Pili li jo e jan pona, meli lili Ana. ona tu li olin musi lon kasi lili. tenpo suno wan la mama pi meli Ana li wile e ni: meli Ana li alasa e moku tawa moku pimeja. meli Ana en soweli Pili li tawa ma kasi li alasa e moku. ona tu li jo e kili loje suli e lipu kasi laso. ona tu li jo e moku la ona tu li tawa sin tawa tomo pi meli Ana. ona tu li moku e moku pona lon tenpo sama. ona tu li pilin pona mute li jo e tenpo suno musi.",
"ts-valid-1097": "tenpo pini la soweli suli wawa li lon. soweli ni li olin kalama wawa. tenpo suno wan la ona li tawa tomo lili. ilo seli li lon tomo. soweli li wile moku. ona li lukin e poki lon sewi pi ilo seli. ona li pilin e ni: moku li lon poki. soweli li tawa poka pi ilo seli li wile lukin e insa poki. taso ilo seli li seli mute. soweli li luka e ilo seli la ona li pilin pakala. ona li kalama wawa tan ni: ona li pilin ike. soweli li tawa weka tan tomo. tenpo ale la ona li kama ala sin.",
"ts-valid-1104": "tenpo pini la soweli len li lon. soweli len li jo e linja len suwi. ona li olin e ni: linja len ona li kama suli. tenpo suno wan la soweli ike li lukin e soweli len. soweli ike li wile e linja len pi soweli len. soweli ike en soweli len li utala suli. soweli len li wile tawa weka. taso soweli ike li tawa wawa. soweli len li pilin monsuta. taso ijo nasa li kama. kasi suli li tawa anpa. kasi li pakala e soweli ike. soweli len li awen pona. taso kasi li pakala e soweli len kin. linja len pi soweli len li kama suli ala. soweli len li pilin ike. pini.",
"ts-valid-1106": "tenpo pini la meli lili Lusi li lon. ona li wile pini pona e ijo. ona li wile alasa e ni: ona li pona e linja lawa ona kepeken ilo pi linja lawa. ni li pali ike. taso pona la mama ona li pana e pona mute tawa ona. meli Lusi li alasa mute. pini la ona li pona e linja lawa ona! ona li pilin suli mute tan ni: ona li pini pona. ona li kama sona e ni: linja lawa ona li pona lukin mute. ona li pilin pona mute. tan tenpo ni la meli Lusi li pona e linja lawa ona lon tenpo suno ale li pilin pona mute.",
"ts-valid-1154": "tenpo pini la mije lili Ten li lon. mije Ten li olin moku e pan. tenpo suno wan la mama ona li pali e pan suli tawa ona. ona li pilin suli mute. mije Ten li tawa ma kasi musi li wile moku e pan ona. ona li awen lon ma li open moku la waso li tawa poka li kama jo e pan ona! mije Ten li pilin ike li wile pini alasa e pan. taso ijo nasa li kama. waso li kama sin li pana e pan lon noka pi mije Ten! mije Ten li pilin pona li moku e pan ona li pilin pona mute.",
"ts-valid-1178": "tenpo suno wan la mije lili Ten en mama ona li tawa ma kasi musi. ona li lukin e waso lon kasi weka. waso li jo e kalama musi pona. mije Ten li wile pali e kalama musi sama. mije Ten li toki tawa mama ona: mama o, mi ken ala ken pali e kalama musi sama waso? mama ona li toki e ni: mije Ten o, ken. o alasa mute. mije Ten li alasa pali e kalama musi. ona li alasa mute. pini la ona li pali e kalama musi lili. ona li pilin pona. waso kin li pilin pona. ona tu li kalama musi lon tenpo sama li musi lon tenpo suno ale.",
"ts-valid-1187": "tenpo pini la mije San li lon. ona li jo e mani mute. mije San li jo e kili lili mute lon poki len suli. tenpo suno wan la ona li tawa ma esun li wile esun e kili lili. lon ma esun la mije San li kama lukin e mije lili Ten. mije Ten li lukin e kili lili li toki e ni: a, kili lili mute a! mi wile e kili lili. mije San li pilin pona li pana e kili lili mute tawa mije Ten. mije San en mije Ten li kama jan pona. ona tu li musi li kalama musi. pini la ona tu li pana e kili lili tawa jan ale lon ma tomo. jan ale li pilin pona mute.",
"ts-valid-1231": "tenpo pini la mije lili Ten li lon. mije Ten li jo e ilo musi pona nanpa wan: sike kiwen lili pona. ona li olin musi e ona lon tenpo suno ale. tenpo suno wan la mije Ten li wile pali ike. ona li pana wawa e sike kiwen tawa jan pona ona, mije San. mije San li toki wawa e ni: a! ni li pakala e mi! mije Ten li pilin ike li toki e ni: mije San o, mi pakala. mi wile ala pakala e sina. mije San li pilin ike. taso ona li sona e ni: mije Ten li pilin pakala. ona li toki e ni: mije Ten o, ni li pona. luka mi li kama pona lon tenpo lili. mije Ten li toki e ni: mi pali ike ala sin. ona en mije San li musi e sike kiwen lon tenpo sama li pilin pona.",
"ts-valid-1238": "tenpo pini la kon pona li lon. ona li olin tawa musi. ona li tawa musi lon tenpo suno ale lon tenpo pimeja ale. ona li tawa musi pona mute la jan ale li lukin e ona li wile jo e pona ona. tenpo suno wan la meli lili Lusi li lukin e ni: kon li tawa musi. meli Lusi li toki e ni: a! mi wile tawa musi sama sina! kon li pilin pona li toki e ni: meli Lusi o, sina ken tawa musi lon poka mi! ni la meli Lusi en kon li tawa musi lon tenpo suno ale. ona tu li pilin musi mute li kama jan pona nanpa wan. jan ale li lukin e ni: ona tu li tawa musi lon tenpo sama. jan ale ni li pilin pona kin.",
"ts-valid-1345": "tenpo pini la soweli telo pona li lon. ona li lon telo suli. ona li olin musi li olin pilin e telo lon selo ona. soweli telo li jo e jan pona mute lon telo suli. tenpo suno wan la soweli telo li kama lukin e kala suli. kala suli li wile musi lon poka pi soweli telo. ona tu li musi lon tenpo sama li pilin musi mute. soweli telo li pilin pona tan jan pona sin. taso kala suli li jan pona pona ala. tenpo suno wan la kala suli li moku e soweli telo. soweli telo li weka. telo suli li pilin ike tan ni: soweli telo pona li lon ala.",
}

